INSERT INTO dealers (userId, name, description, address, city, postcode, phone, email, whatsappNumber, isVerified, subscriptionStatus, subscriptionExpiresAt, createdAt, updatedAt)
SELECT id, 'EVEEVO Admin Dealer', 'Admin dealer account for testing', '123 Admin Street', 'London', 'SW1A 1AA', '07700900001', 'anthony.m.perry@gmail.com', '447700900001', 1, 'active', DATE_ADD(NOW(), INTERVAL 1 YEAR), NOW(), NOW()
FROM users WHERE email = 'anthony.m.perry@gmail.com'
LIMIT 1
